From fc0f70564598dadeb04e3cdb2694de830ca979f5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:29:37 +0100
Subject: [PATCH] containmentlayoutmanager: follow KWin's blur strength on
 widgets

Desktop widgets aren't windows, so they blur the wallpaper on their own
and always used the strongest blur, whatever strength is set for KWin's
Blur effect. Read that strength from kwinrc and match the widget blur.

BUG: 512579
---
 .../containmentlayoutmanager/CMakeLists.txt   |  1 +
 .../plasmabackground.cpp                      | 33 +++++++++++++++++++
 .../plasmabackground.h                        | 11 +++++++
 .../qml/BasicAppletContainer.qml              |  2 +-
 4 files changed, 46 insertions(+), 1 deletion(-)

diff --git a/components/containmentlayoutmanager/CMakeLists.txt b/components/containmentlayoutmanager/CMakeLists.txt
index 90b469f4c4..a518679146 100644
--- a/components/containmentlayoutmanager/CMakeLists.txt
+++ b/components/containmentlayoutmanager/CMakeLists.txt
@@ -35,6 +35,7 @@ target_link_libraries(containmentlayoutmanagerplugin
         PRIVATE
             Qt::Qml Qt::Quick
             Plasma::Plasma Plasma::PlasmaQuick
+            KF6::ConfigCore
     )

 ecm_qt_declare_logging_category(containmentlayoutmanagerplugin
diff --git a/components/containmentlayoutmanager/plasmabackground.cpp b/components/containmentlayoutmanager/plasmabackground.cpp
index 6331f70283..dc9950a9a5 100644
--- a/components/containmentlayoutmanager/plasmabackground.cpp
+++ b/components/containmentlayoutmanager/plasmabackground.cpp
@@ -6,9 +6,42 @@

 #include "plasmabackground.h"

+#include <KConfigGroup>
+
+#include <algorithm>
+#include <array>
+
 PlasmaBackground::PlasmaBackground()
+    : m_kwinConfig(KSharedConfig::openConfig(QStringLiteral("kwinrc"), KConfig::NoGlobals))
+    , m_kwinConfigWatcher(KConfigWatcher::create(m_kwinConfig))
 {
     connect(&m_theme, &Plasma::Theme::themeChanged, this, &PlasmaBackground::themeChanged);
+    connect(m_kwinConfigWatcher.data(), &KConfigWatcher::configChanged, this, [this](const KConfigGroup &group, const QByteArrayList &names) {
+        if (group.name() == QLatin1String("Effect-blur") && names.contains(QByteArrayLiteral("BlurStrength"))) {
+            readBlurStrength();
+        }
+    });
+
+    readBlurStrength();
+}
+
+void PlasmaBackground::readBlurStrength()
+{
+    // Reach (offset * 2^iterations) of KWin's dual Kawase blur at strengths 1 to 15;
+    // keep in sync with BlurEffect::initBlurStrengthValues() in KWin's blur plugin.
+    static constexpr std::array<qreal, 15> radii = {3, 4, 10, 12, 20.8, 25.6, 30.4, 35.2, 40, 61.33, 74.67, 88, 101.33, 114.67, 128};
+
+    const int strength = KConfigGroup(m_kwinConfig, QStringLiteral("Effect-blur")).readEntry("BlurStrength", 15);
+    const qreal radius = radii[std::clamp(strength, 1, 15) - 1];
+    if (radius != m_blurRadius) {
+        m_blurRadius = radius;
+        Q_EMIT blurRadiusChanged();
+    }
+}
+
+qreal PlasmaBackground::blurRadius() const
+{
+    return m_blurRadius;
 }

 qreal PlasmaBackground::backgroundContrast() const
diff --git a/components/containmentlayoutmanager/plasmabackground.h b/components/containmentlayoutmanager/plasmabackground.h
index 3252d538fc..de1d7a9e21 100644
--- a/components/containmentlayoutmanager/plasmabackground.h
+++ b/components/containmentlayoutmanager/plasmabackground.h
@@ -9,6 +9,8 @@
 #include <QObject>
 #include <qqmlregistration.h>

+#include <KConfigWatcher>
+#include <KSharedConfig>
 #include <Plasma/Theme>

 class PlasmaBackground : public QObject
@@ -20,6 +22,8 @@ class PlasmaBackground : public QObject
     Q_PROPERTY(qreal backgroundContrast READ backgroundContrast NOTIFY themeChanged)
     Q_PROPERTY(qreal backgroundIntensity READ backgroundIntensity NOTIFY themeChanged)
     Q_PROPERTY(qreal backgroundSaturation READ backgroundSaturation NOTIFY themeChanged)
+    // Matches the reach of KWin's blur at its configured strength, in pixels
+    Q_PROPERTY(qreal blurRadius READ blurRadius NOTIFY blurRadiusChanged)

 public:
     PlasmaBackground();
@@ -27,10 +31,17 @@ public:
     qreal backgroundContrast() const;
     qreal backgroundIntensity() const;
     qreal backgroundSaturation() const;
+    qreal blurRadius() const;

 Q_SIGNALS:
     void themeChanged();
+    void blurRadiusChanged();

 private:
+    void readBlurStrength();
+
     Plasma::Theme m_theme;
+    KSharedConfigPtr m_kwinConfig;
+    KConfigWatcher::Ptr m_kwinConfigWatcher;
+    qreal m_blurRadius = 0;
 };
diff --git a/components/containmentlayoutmanager/qml/BasicAppletContainer.qml b/components/containmentlayoutmanager/qml/BasicAppletContainer.qml
